enum class Page(val label:String,val icon:String){Home("Home","⌂"),Laptop("Laptop","💻"),Desktop("Desktop","🖥"),GP("GP","$"),More("More","⚙")}
enum class MatchTier{EXACT,SIMILAR,REJECTED}
data class Features(val brand:String="",val family:String="",val cpu:String="",val gpu:String="",val ram:String="",val storage:String="",val modelTokens:List<String> = emptyList())
data class Listing(val title:String,val price:Double,val source:String,val url:String,val condition:String,val tier:MatchTier,val score:Int,val reasons:String)
data class ComponentValue(val label:String,val query:String,val value:Double,val evidence:List<Listing>)
data class MarketResult(val exactGoogle:List<Listing>,val exactEbay:List<Listing>,val similarGoogle:List<Listing>,val similarEbay:List<Listing>,val rejected:List<Listing>,val components:List<ComponentValue> = emptyList())
private val brands=listOf("apple","lenovo","dell","hp","acer","asus","msi","alienware","gigabyte","razer","microsoft","thermaltake","corsair")
private val families=listOf("mpg trident as","trident as","trident","macbook pro","macbook air","thinkcentre","thinkstation","thinkpad","optiplex","precision","elitedesk","prodesk","legion","loq","omen","victus","predator","nitro","tuf","rog","zephyrus","vivobook","zenbook","inspiron","latitude","xps","aegis","infinite","codex","surface laptop")
private fun norm(s:String)=s.lowercase().replace(Regex("[^a-z0-9]+")," ").replace(Regex("\\s+")," ").trim()
private fun features(s:String):Features{val x=norm(s);val brand=brands.firstOrNull{x.contains(Regex("\\b${Regex.escape(it)}\\b"))}.orEmpty();val family=families.firstOrNull{x.contains(it)}.orEmpty();val cpu=Regex("\\b(?:i[3579][ -]?)?(\\d{4,5}[a-z]{0,3})\\b").find(x)?.groupValues?.get(1).orEmpty();val gpu=Regex("\\b((?:rtx|gtx|rx|arc)\\s*\\d{3,4}(?:\\s*(?:ti|super|xt|xtx))?)\\b").find(x)?.groupValues?.get(1).orEmpty();val ram=Regex("\\b(8|12|16|18|24|32|36|48|64|96|128)\\s*gb\\b").find(x)?.groupValues?.get(1).orEmpty();val storage=Regex("\\b(?:128|256|512)\\s*gb\\b|\\b(?:1|2|4|8)\\s*tb\\b").find(x)?.value.orEmpty();val tokens=x.split(" ").filter{it.length>=4&&it.any(Char::isLetter)&&it.any(Char::isDigit)&&it!=cpu};return Features(brand,family,cpu,gpu,ram,storage,tokens)}
private fun classify(query:String,title:String):Triple<MatchTier,Int,String>{val q=features(query);val t=features(title);val tx=norm(title);var score=0;val r=mutableListOf<String>();val brandMismatch=q.brand.isNotBlank()&&t.brand.isNotBlank()&&q.brand!=t.brand;if(q.brand.isNotBlank()&&q.brand==t.brand){score+=30;r+="Brand"};if(q.family.isNotBlank()&&tx.contains(q.family)){score+=40;r+="Exact family"};val hits=q.modelTokens.count{tx.contains(Regex("\\b${Regex.escape(it)}\\b"))};if(hits>0){score+=minOf(18,hits*9);r+="Model"};if(q.cpu.isNotBlank()&&tx.contains(Regex("\\b${Regex.escape(q.cpu)}\\b"))){score+=14;r+="CPU"};if(q.gpu.isNotBlank()&&tx.contains(norm(q.gpu))){score+=14;r+="GPU"};if(q.ram.isNotBlank()&&tx.contains(Regex("\\b${q.ram}\\s*gb\\b"))){score+=5;r+="RAM"};if(q.storage.isNotBlank()&&tx.contains(norm(q.storage))){score+=5;r+="Storage"};score=score.coerceAtMost(100);val accessory=Regex("\\b(cable|adapter|charger|battery|keyboard|mouse|case|cover|stand|webcam|module|ssd|ram kit|memory|motherboard|heatsink|fan|screen|display|replacement|part|parts)\\b").containsMatchIn(tx);val exact=!brandMismatch&&!accessory&&q.brand.isNotBlank()&&q.brand==t.brand&&((q.family.isNotBlank()&&tx.contains(q.family))||(q.modelTokens.isNotEmpty()&&hits==q.modelTokens.size));val similar=!accessory&&!exact&&score>=18;val tier=when{exact->MatchTier.EXACT;similar->MatchTier.SIMILAR;else->MatchTier.REJECTED};if(brandMismatch)r+="Different brand";if(accessory)r+="Part/accessory";return Triple(tier,score,r.distinct().joinToString(" + "))}
private fun median(v:List<Double>):Double{val s=v.filter{it>0}.sorted();if(s.isEmpty())return 0.0;val m=s.size/2;return if(s.size%2==1)s[m] else (s[m-1]+s[m])/2}
private fun money(v:Double)=NumberFormat.getCurrencyInstance(Locale("en","AU")).apply{maximumFractionDigits=0}.format(v)
