@Composable fun Laptop()=Screen("💻 Laptop / MacBook"){var q by remember{mutableStateOf("")};var ask by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var result by remember{mutableStateOf<MarketResult?>(null)};var status by remember{mutableStateOf("Ready")};val scope=rememberCoroutineScope();Field("Exact model / clean search",q,{q=it});Field("Seller asking price",ask,{ask=it},true);Btn(if(busy)"Searching…" else "Analyse Laptop",{busy=true;scope.launch{runCatching{market(q)}.onSuccess{result=it;status=summary(it)}.onFailure{status=it.message?:"Search failed"};busy=false}},!busy&&q.isNotBlank());Text(status,color=Color.LightGray);result?.let{Valuation(it,ask,0.30,0.58)}}
