@Composable fun More()=Screen("⚙ More"){val context=LocalContext.current;val scope=rememberCoroutineScope();var checking by remember{mutableStateOf(false)};var status by remember{mutableStateOf("Automatic update checks are ready.")};var update by remember{mutableStateOf<AppUpdate?>(null)};Block("B&L MORLEY","Native Android v${BuildConfig.VERSION_NAME}");Block("VALUATION SAFETY","Primary prices require verified OEM/model matches. Similar and wrong-brand whole-PC results cannot drive Max Buy. Component fallback requires independently validated part matches.");Block("OTA UPDATES",status);Btn(if(checking)"Checking…" else "Check for Updates",{checking=true;scope.launch{runCatching{UpdateManager.check()}.onSuccess{u->update=u;status=if(u==null)"You're up to date." else "${u.versionName} is available. ${u.notes}"}.onFailure{status="Update check failed: ${it.message?:"network error"}"};checking=false}},!checking);update?.let{Btn("Download ${it.versionName}",{if(android.os.Build.VERSION.SDK_INT>=26&&!context.packageManager.canRequestPackageInstalls())UpdateManager.openInstallerPermission(context) else UpdateManager.openDownload(context,it)})}}
